        <Button 
          onClick={() => setIsStartBatchModalOpen(true)} 
          className="relative z-10 bg-gradient-to-r from-gold-500 to-gold-600 hover:from-gold-600 hover:to-gold-700 text-white shadow-lg shadow-gold-500/20 px-8 py-6 rounded-xl font-black uppercase tracking-widest transition-all active:scale-95"
        >
          <Play className="w-5 h-5 mr-2 fill-current" />
          Start Production Batch
        </Button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Details & Instructions */}
        <div className="lg:col-span-2 space-y-6">
          <Card className="border-chocolate-100 overflow-hidden shadow-sm">
            <CardHeader className="bg-chocolate-50/50 border-b border-chocolate-100/50 pb-4">
              <CardTitle className="flex items-center gap-2 text-lg font-black text-chocolate-900 uppercase tracking-wide">
                <Info className="w-5 h-5 text-gold-500" />
                Recipe Profile
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <p className="text-chocolate-600 leading-relaxed font-medium">{recipe.description}</p>
            </CardContent>
          </Card>

          <Card className="border-chocolate-100 overflow-hidden shadow-sm">
            <CardHeader className="bg-chocolate-50/50 border-b border-chocolate-100/50 pb-4">
              <CardTitle className="flex items-center gap-2 text-lg font-black text-chocolate-900 uppercase tracking-wide">
                <ChefHat className="w-5 h-5 text-gold-500" />
                Production Workflow
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="space-y-6">
                {recipe.instructions.map((step, index) => (
                  <div key={index} className="flex gap-4 group">
                    <div className="flex-shrink-0 w-8 h-8 rounded-xl bg-chocolate-100 text-chocolate-800 flex items-center justify-center font-black text-sm shadow-sm group-hover:bg-gold-500 group-hover:text-white transition-colors duration-300">
                      {index + 1}
                    </div>
                    <p className="text-chocolate-700 mt-1 font-medium leading-relaxed">{step}</p>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Right Column: Ingredients */}
        <div className="space-y-6">
          <Card className="h-full border-chocolate-100 overflow-hidden shadow-sm">
            <CardHeader className="bg-chocolate-50/50 border-b border-chocolate-100/50 pb-4">
              <CardTitle className="flex items-center gap-2 text-lg font-black text-chocolate-900 uppercase tracking-wide">
                <Scale className="w-5 h-5 text-gold-500" />
                Bill of Materials
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="space-y-3">
                {recipe.ingredients.map((ingredient: RecipeIngredient) => (
                  <div key={ingredient.id} className="flex items-center justify-between p-4 bg-white rounded-xl border border-chocolate-100 shadow-sm hover:border-gold-300 transition-colors">
                    <div>
                      <p className="font-bold text-chocolate-900">{ingredient.name}</p>
                      <p className="text-[10px] font-black text-chocolate-400 uppercase tracking-wider">{ingredient.code ?? 'NO CODE'}</p>
                    </div>
                    <div className="text-right">
                      <p className="font-black text-xl text-chocolate-800">
                        {ingredient.quantity} <span className="text-[10px] uppercase text-chocolate-400 font-bold">{ingredient.unit}</span>
                      </p>
                    </div>
                  </div>
                ))}
              </div>
              
              <div className="mt-8 p-6 bg-gradient-to-br from-gold-50 to-white rounded-2xl border border-gold-200/50 shadow-inner">
                <h4 className="text-xs font-black text-gold-700 mb-2 uppercase tracking-widest flex items-center gap-2">
                  <AlertTriangle className="w-3 h-3" /> Master Chocolatier Tip
                </h4>
                <p className="text-xs text-chocolate-600/80 font-medium italic leading-relaxed">
                  "Maintain ingredient acclimation at 22°C ambient temperature for optimal crystallization phases."
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Start Batch Modal */}
      {recipe && (
        <StartBatchModal
          isOpen={isStartBatchModalOpen}
          onClose={() => setIsStartBatchModalOpen(false)}
          recipe={recipe}
        />
      )}
    </div>
  );
};

export default RecipeDetailPage;

import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import LoginPage from './pages/auth/LoginPage';
import DashboardPage from './pages/dashboard/DashboardPage';
import InventoryPage from './pages/inventory/InventoryPage';
import ProductionPage from './pages/production/ProductionPage';
import SalesPage from './pages/sales/SalesPage';
import AppLayout from './components/layout/AppLayout';
import { useAuthStore } from './store/auth';

function ProtectedRoute({ children }: { children: React.ReactElement }) {
  const isAuth = useAuthStore((s: any) => s.isAuthenticated());
  return isAuth ? children : <Navigate to="/login" replace />;
}

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/login" element={<LoginPage />} />

        <Route element={<ProtectedRoute><AppLayout /></ProtectedRoute>}>
          <Route path="/" element={<DashboardPage />} />
          <Route path="/inventory" element={<InventoryPage />} />
          <Route path="/production" element={<ProductionPage />} />
          <Route path="/sales" element={<SalesPage />} />
          <Route path="/chat" element={<div>Chat Full Page (Coming Soon)</div>} />
        </Route>

         {/* Catch all */}
         <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
}

export default App;

import { useState, useEffect, useCallback } from 'react';
import api from '@/data/infrastructure/httpClient';
import { toast } from 'sonner';
import { Plus, Loader2 } from 'lucide-react';

interface Batch {
  id: string;
  recipe_id: string;
  quantity_produced: number;
  status: string;
  created_at: string;
}

interface Ingredient {
  id: string;
  name: string;
  current_stock: number;
  unit: string;
}

export default function ProductionPage() {
  const [batches, setBatches] = useState<Batch[]>([]);
  const [ingredients, setIngredients] = useState<Ingredient[]>([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({
    recipe_id: '',
    quantity_produced: '',
    ingredients: [{ ingredient_id: '', quantity: 0 }],
  });

  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const [batchesRes, ingRes] = await Promise.all([
        api.get('/production/batches'),
        api.get('/inventory'),
      ]);
      setBatches(batchesRes.data.data ?? []);
      setIngredients(ingRes.data.data ?? []);
    } catch (err: unknown) {
      console.error(err);
      toast.error('Failed to load production data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const addIngredient = () => {
    setForm({
      ...form,
      ingredients: [...form.ingredients, { ingredient_id: '', quantity: 0 }],
    });
  };

  const updateIngredient = (index: number, field: 'ingredient_id' | 'quantity', value: string | number) => {
    const newIng = [...form.ingredients];
    newIng[index] = { ...newIng[index], [field]: value };
    setForm({ ...form, ingredients: newIng });
  };

  const createBatch = async () => {
    if (!form.recipe_id || !form.quantity_produced) {
      toast.error('Recipe ID and quantity are required');
      return;
    }

    try {
      await api.post('/production/batches', form);
      
      // Reset form
      setForm({ 
        recipe_id: '', 
        quantity_produced: '', 
        ingredients: [{ ingredient_id: '', quantity: 0 }] 
      });

      // Refresh list
      const res = await api.get('/production/batches');
      setBatches(res.data.data ?? []);
      
      toast.success('Batch created successfully');
    } catch (err) {
      console.error(err);
      toast.error('Failed to create batch');
    }
  };

  return (
    <div className="space-y-8">
      <h1 className="text-2xl font-bold text-gray-900">Production Management</h1>

      {/* Create Batch Form */}
      <div className="bg-white p-6 rounded-xl shadow border border-secondary-200">
        <h2 className="text-xl font-semibold mb-4 text-secondary-900">Create New Batch</h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Recipe ID</label>
            <input
              type="text"
              value={form.recipe_id}
              onChange={e => setForm({ ...form, recipe_id: e.target.value })}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
              placeholder="recipe-uuid-123"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">Quantity Produced</label>
            <input
              type="number"
              value={form.quantity_produced}
              onChange={e => setForm({ ...form, quantity_produced: e.target.value })}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
              min="1"
            />
          </div>
        </div>

        <div className="mb-6">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-lg font-semibold text-secondary-900">Ingredients</h3>
            <button
              type="button"
              onClick={addIngredient}
              className="flex items-center gap-1 text-indigo-600 hover:text-indigo-800 text-sm font-medium"
            >
              <Plus size={16} />
              Add Ingredient
            </button>
          </div>

          {form.ingredients.map((ing, idx) => (
            <div key={idx} className="flex gap-4 mb-3">
              <select
                value={ing.ingredient_id}
                onChange={e => updateIngredient(idx, 'ingredient_id', e.target.value)}
                className="flex-1 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
              >
                <option value="">Select Ingredient</option>
                {ingredients.map(i => (
                  <option key={i.id} value={i.id}>
                    {i.name} ({i.current_stock} {i.unit} available)
                  </option>
                ))}
              </select>
              <input
                type="number"
                value={ing.quantity}
                onChange={e => updateIngredient(idx, 'quantity', Number(e.target.value))}
                className="w-32 px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-amber-500"
                placeholder="Qty"
                min="0.1"
                step="0.1"
              />
            </div>
          ))}
        </div>

        <button
          onClick={createBatch}
          className="bg-indigo-600 text-white px-6 py-3 rounded-lg hover:bg-indigo-700 transition font-medium"
        >
          Create Batch
        </button>
      </div>

      {/* Batch List */}
      <div className="bg-white rounded-xl shadow border border-secondary-200 overflow-hidden">
        <div className="p-6 border-b border-secondary-200">
          <h2 className="text-xl font-semibold text-secondary-900">Active Batches</h2>
        </div>

        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-200">
            <thead className="bg-gray-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">ID</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Recipe</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Quantity</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Created</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200 bg-white">
              {loading ? (
                <tr>
                  <td colSpan={5} className="px-6 py-8 text-center">
                    <Loader2 className="animate-spin h-8 w-8 text-indigo-600 mx-auto" />
                    <p className="mt-2 text-sm text-gray-500">Loading batches...</p>
                  </td>
                </tr>
              ) : batches.length === 0 ? (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-gray-500">
                    No active batches found
                  </td>
                </tr>
              ) : (
                batches.map(batch => (
                  <tr key={batch.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                      {batch.id.slice(0, 8)}...
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {batch.recipe_id}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {batch.quantity_produced}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                        batch.status === 'COMPLETED' ? 'bg-green-100 text-green-800' :
                        batch.status === 'IN_PROGRESS' ? 'bg-yellow-100 text-yellow-800' :
                        'bg-gray-100 text-gray-800'
                      }`}>
                        {batch.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      {new Date(batch.created_at).toLocaleDateString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
